function readline() {
    let line;
    try {
        line = require('readline').createInterface({
            input: process.stdin
        });
    } catch (e) {
        line = null;
    }
    if (line) {
        return new Promise((resolve) => {
            line.question('', (answer) => {
                line.close();
                resolve(answer);
            });
        });
    }
    return Promise.resolve(require('fs').readFileSync(0, 'utf8').trim());
}

run().then(s => {
    const ok = doit(s);
    console.log(ok ? "YES" : "NO");
});

