using System;
using System.Text.RegularExpressions;

namespace AllProblems
{
    class Program
    {
        static void Main(string[] args)
        {
            _538A_CuttingBanner.Run();
        }
    }
    public class _538A_CuttingBanner
    {
        private const string WORD = "CODEFORCES";

        public static void Run()
        {
            var s = Console.ReadLine();            

            var ok = doit(s);

            Console.WriteLine(ok ? "YES" : "NO");
        }

        private static bool doit(string word) {
            if (word.StartsWith(WORD) || word.EndsWith(WORD)) return true;
            for(var i = 1; i < WORD.Length; i++) {
                var pat = "^"+WORD.Substring(0, i) + ".*" + WORD.Substring(i) +"$";
                if (Regex.Match(word, pat).Success) return true;
            }
            return false;
        }
    }
}
